const test = require("node:test");
const assert = require("node:assert/strict");
const { apply, modelView } = require("../ai-action-plan.js");

const tracks = [{ id: "V3", kind: "video" }, { id: "V2", kind: "video" }, { id: "V1", kind: "video" }];
const resource = { id: "annotation.rect.svg", runtime: "svg", name: "闭合矩形", props: { duration: { default: 3 }, x: { default: 0 } } };
const capabilityIds = ["close_gap", "create_marker", "delete_marker", "duplicate_clip", "insert_media", "insert_native_component", "insert_subtitle", "insert_text", "move_clip", "remove_clip", "replace_source", "resize_clip", "set_audio_props", "set_clip_props", "set_component_props", "set_marker_color", "set_speed", "split_clip", "trim_head", "trim_tail"].map((id) => `${id}@1`);
function fnv1a64(value) {
  let hash = 0xcbf29ce484222325n;
  for (const byte of new TextEncoder().encode(value)) { hash ^= BigInt(byte); hash = BigInt.asUintN(64, hash * 0x100000001b3n); }
  return hash.toString(16).padStart(16, "0");
}
const capabilitySnapshot = {
  schemaVersion: "orbit.capability-snapshot.v1", version: 1, contractIds: capabilityIds,
  capabilities: capabilityIds.map((value) => {
    const id = value.slice(0, -2);
    const target = id === "create_marker" ? "timeline" : (id === "close_gap" ? "track" : (id.includes("marker") ? "marker" : (id.startsWith("insert") ? "playhead" : "selected_clip")));
    const fieldNames = id === "create_marker" ? ["timelineFrame", "label", "color", "clipId", "localFrame"] : [];
    return { id, version: "1", inputSchema: { type: "object", properties: Object.fromEntries(fieldNames.map((field) => [field, { type: "any" }])) }, targetTypes: [target], permissionCategory: id.includes("marker") ? "marker.write" : "project.write", mutatesProject: true, externalSideEffects: [], selectionPolicy: "explicit_or_resolved", unitPolicy: "frames_at_project_fps", coalescingPolicy: "one_transaction", lockPolicy: "reject_locked", playbackPolicy: "preserve_playhead", limits: { maxOperations: 64, maxTargets: 64 }, undoScope: "project_transaction", collisionPolicy: "fail", trackPlacementPolicy: "specified_or_auto", linkedMediaPolicy: "preserve_linked", taskPolicy: { mode: "synchronous", resourceClass: "cpu", priority: 50, cancellableUntil: "commit", resumable: false, maxConcurrency: 1, diskReservation: 0, progressAdapter: "none" }, executionMode: "local_transaction", reversibility: "undoable", allowedPolicies: ["collision", "trackPlacement", "linkedMedia", "marker"], markerPolicy: "preserve", validate: "schema_and_target", execute: "timeline_executor", postconditions: ["project_hash_changed", "visible_state_verified"], preview: "timeline_preview", render: "timeline_render", verificationAdapter: "timeline.visible" };
  }),
};
capabilitySnapshot.canonical = {
  schemaVersion: capabilitySnapshot.schemaVersion,
  version: capabilitySnapshot.version,
  contractIds: [...capabilitySnapshot.contractIds],
  capabilities: capabilitySnapshot.capabilities,
};
capabilitySnapshot.hash = `fnv1a64:${fnv1a64(JSON.stringify({ schemaVersion: capabilitySnapshot.schemaVersion, version: capabilitySnapshot.version, contractIds: capabilitySnapshot.contractIds, capabilities: capabilitySnapshot.capabilities }))}`;
function context(clips = []) {
  return { project: { revision: 7, fps: 30, clips }, resources: [resource], tracks, playhead: 2, capabilitySnapshot, nextClipId: () => "c_ai" };
}
function plan(operations) { return { schemaVersion: "orbit.bound-action-plan.v2", requestId: "test", baseProjectRevision: 7, operations }; }
function boundPlan(operations) { return { schemaVersion: "orbit.bound-action-plan.v2", requestId: "bound-test", baseProjectRevision: 7, operations }; }

test("capability model view is generated by the registry and exposes execution contracts", () => {
  const view = modelView(capabilitySnapshot);
  assert.ok(view.length >= 19);
  const ids = view.map((item) => item.id);
  assert.equal(new Set(ids).size, ids.length);
  const marker = view.find((item) => item.id === "create_marker");
  assert.equal(marker.permissionCategory, "marker.write");
  assert.equal(marker.verificationAdapter, "timeline.visible");
  assert.ok(marker.inputSchema.properties.timelineFrame);
  assert.equal(marker.executor, undefined);
  assert.equal(marker.reversible, undefined);
});

test("model view validates the injected runtime registry snapshot", () => {
  assert.equal(modelView(capabilitySnapshot).length, capabilitySnapshot.capabilities.length);
  assert.throws(() => modelView(undefined), /缺少宿主/);
  assert.throws(() => modelView({ ...capabilitySnapshot, contractIds: ["wrong@1"] }), /注册表快照/);
  assert.throws(() => modelView({ ...capabilitySnapshot, hash: "fnv1a64:wrong" }), /hash/);
  assert.throws(() => modelView({ ...capabilitySnapshot, version: 0 }), /缺少宿主/);
  assert.throws(() => modelView({ ...capabilitySnapshot, canonical: { ...capabilitySnapshot.canonical, contractIds: ["wrong@1"] } }), /canonical/);
});

test("ActionPlan inserts a verified native component onto the first free upper track", () => {
  const clips = [{ id: "c_existing", kind: "component", track: "V2", start: 2, duration: 3, props: {} }];
  const result = apply(plan([{ type: "insert_native_component", resourceId: resource.id }]), context(clips));
  assert.equal(result.clips.length, 2);
  assert.equal(result.clips[1].track, "V3");
  assert.equal(result.clips[1].componentId, resource.id);
  assert.deepEqual(clips, [{ id: "c_existing", kind: "component", track: "V2", start: 2, duration: 3, props: {} }]);
  assert.ok(result.receipt.affectedIds.includes(result.clips[1].id));
});

test("ActionPlan adds a new upper video track instead of reporting a collision", () => {
  const clips = tracks.map((track) => ({ id: `c_${track.id}`, kind: "component", track: track.id, start: 2, duration: 3, props: {} }));
  const result = apply(plan([{ type: "insert_native_component", resourceId: resource.id }]), context(clips));
  assert.equal(result.clips.at(-1).track, "V4");
  assert.deepEqual(result.tracks.at(-1), { id: "V4", kind: "video" });
});

test("ActionPlan rejects stale revisions, unknown resources, and retains the project on failure", () => {
  assert.throws(() => apply({ ...plan([{ type: "insert_native_component", resourceId: resource.id }]), baseProjectRevision: 6 }, context()), /已过期/);
  assert.throws(() => apply(plan([{ type: "insert_native_component", resourceId: "unknown" }]), context()), /未验证/);
  assert.throws(() => apply(plan([{ type: "remove_clip", targetId: "missing" }]), context()), /目标已不存在/);
});

test("ActionPlan validates every operation before returning a timeline", () => {
  const clips = [{ id: "c_1", kind: "component", track: "V2", start: 0, duration: 2, props: { x: 0 } }];
  assert.throws(() => apply(plan([
    { type: "set_component_props", targetId: "c_1", props: { x: 20 } },
    { type: "move_clip", targetId: "c_1", timelineStart: -1 },
  ]), context(clips)), /移动参数无效/);
  assert.deepEqual(clips[0].props, { x: 0 });
});

test("ActionPlan accepts only component properties declared by the native manifest", () => {
  const clips = [{ id: "c_1", kind: "component", componentId: resource.id, track: "V2", start: 0, duration: 2, props: { x: 0 } }];
  assert.throws(() => apply(plan([
    { type: "set_component_props", targetId: "c_1", props: { shellCommand: "unsafe" } },
  ]), context(clips)), /组件协议中声明/);
  assert.throws(() => apply(plan([
    { type: "set_component_props", targetId: "c_1", props: { x: "20" } },
  ]), context(clips)), /数值属性无效/);
});

test("BoundActionPlan v2 applies markers, split, trim, and media replacement atomically", () => {
  const media = [{ id: "media-next", kind: "video", name: "next", duration: 8 }];
  const clips = [{ id: "c_1", mediaId: "media-old", kind: "video", track: "V1", start: 0, duration: 4, in: 0, props: {} }];
  const result = apply(boundPlan([
    { type: "split_clip", targetId: "c_1", atFrame: 60 },
    { type: "replace_source", targetId: "c_1", mediaId: "media-next" },
    { type: "create_marker", timelineFrame: 30, label: "beat", color: "red" },
  ]), { ...context(clips), media });
  assert.equal(result.clips.length, 2);
  assert.equal(result.clips[0].mediaId, "media-next");
  assert.equal(result.markers[0].color, "red");
  assert.ok(result.receipt.affectedIds.some((id) => String(id) === String(result.markers[0].markerId)));
});

test("ActionPlan receipt distinguishes removed targets for preview verification", () => {
  const clips = [{ id: "c_1", kind: "video", track: "V1", start: 0, duration: 2, props: {} }];
  const result = apply(plan([{ type: "remove_clip", targetId: "c_1" }]), context(clips));
  assert.deepEqual(result.clips, []);
  assert.deepEqual(result.receipt.removedIds, ["c_1"]);
  assert.ok(result.receipt.affectedIds.includes("c_1"));
});

test("C++ bound operation shape is materialized by the single frontend executor", () => {
  const clips = [{ id: "c_1", kind: "video", track: "V1", start: 0, duration: 4, in: 0, props: {} }];
  const result = apply({
    schemaVersion: "orbit.bound-action-plan.v2", requestId: "bound-shape", baseProjectRevision: 7,
    capabilitySet: { version: 1, hash: capabilitySnapshot.hash },
    referenceSnapshotId: "ref-1",
    operations: [{ operationId: "op-1", capability: "resize_clip",
      target: { kind: "selected_clip", id: "c_1", resolvedFrom: "selected_clip" },
      args: { durationFrames: 60 }, policies: { collisionPolicy: "fail", trackPlacementPolicy: "auto", linkedMediaPolicy: "preserve", markerPolicy: "preserve" },
      dependsOn: [], preconditions: [{ projectRevision: 7, targetVersion: 0 }], readSet: ["c_1"], writeSet: ["c_1"],
      resolutionEvidence: { referenceSnapshotId: "ref-1" } }],
  }, { ...context(clips), project: { ...context(clips).project, clips } });
  assert.equal(result.clips[0].duration, 2);
});

test("capability matrix executes subtitle, audio, marker, and gap operations", () => {
  const clips = [
    { id: "c_audio", kind: "audio", track: "A1", start: 0, duration: 4, props: {} },
    { id: "c_later", kind: "video", track: "V1", start: 2, duration: 1, props: {} },
  ];
  const result = apply(plan([
    { type: "insert_subtitle", text: "字幕", timelineStart: 0, durationFrames: 30, track: "V1" },
    { type: "set_audio_props", targetId: "c_audio", props: { volume: 0.5 } },
    { type: "create_marker", timelineFrame: 30, label: "beat", color: "blue" },
    { type: "close_gap", track: "V1", startFrame: 0, endFrame: 30 },
  ]), { ...context(clips), project: { revision: 7, fps: 30, clips, markers: [] }, media: [] });
  assert.equal(result.clips.find((clip) => clip.name === "字幕").kind, "subtitle");
  assert.equal(result.clips[0].props.volume, 0.5);
  assert.equal(result.clips.find((clip) => clip.id === "c_later").start, 1);
  assert.equal(result.markers.length, 1);

  const markerId = result.markers[0].markerId;
  assert.throws(() => apply(plan([
    { type: "set_marker_color", markerId, color: "purple" },
    { type: "delete_marker", markerId: "missing" },
  ]), { ...context(result.clips), project: { revision: 7, fps: 30, clips: result.clips, markers: result.markers } }), /标记不存在/);
  assert.equal(result.markers[0].color, "blue");
});

test("locked clips and tracks are rejected before any capability mutates the transaction", () => {
  const clips = [{ id: "locked", kind: "video", track: "V1", start: 0, duration: 2, locked: true, props: {} }];
  assert.throws(() => apply(plan([{ type: "resize_clip", targetId: "locked", durationFrames: 30 }]), context(clips)), /已锁定/);
  const tracksWithLock = [{ id: "V1", kind: "video", locked: true }];
  assert.throws(() => apply(plan([{ type: "close_gap", track: "V1", startFrame: 0, endFrame: 30 }]), { ...context(clips), tracks: tracksWithLock }), /已锁定/);
});
